import{z as i,x as A,o,c as B,q as n,j as E,D as l,d as r,s,S as d,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"λ 演算","description":"","frontmatter":{"title":"λ 演算","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lambda-calculus.md","filePath":"cs/lambda-calculus.md","lastUpdated":1791413859000}'),m={name:"cs/lambda-calculus.md"};function h(p,a,u,c,x,C){const t=A("Mermaid");return o(),B("div",null,[a[2]||(a[2]=n('<h1 id="λ-演算" tabindex="-1">λ 演算 <a class="header-anchor" href="#λ-演算" aria-label="Permalink to &quot;λ 演算&quot;">​</a></h1><div class="epigraph"><p>项由变量、抽象 $\\lambda x.M$ 与应用 $MN$ 建成；β 归约是计算。Church 用它定义可计算，与图灵机等价。</p><footer>—— 据 Church, The Calculi of Lambda-Conversion, 1941；Barendregt, The Lambda Calculus 整理</footer></div><p>上一课<a href="/cs/kolmogorov-complexity">Kolmogorov 复杂度</a>的程序仍是 TM 带上的串。Church–Turing 论题点名过 λ，尚未展开。缺口是<strong>无类型 λ 演算</strong>：另一套计算的语法。本课钉项、自由变量、β、Church 数字；组合子与 \\(Y\\) 下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TM 把状态与带混在表里，函数是事后编码。λ：一切都是项。\\(\\lambda x.M\\) 绑定，\\(MN\\) 应用。\\((\\lambda x.M)N\\to_\\beta M[N/x]\\)（小心捕获）。规范化：有的项无范式（\\(\\Omega=(\\lambda x.xx)(\\lambda x.xx)\\)），对应 TM 循环。可计算函数：Church 编码的 \\(\\mathbb{N}\\to\\mathbb{N}\\) 上有范式的项。</p><p>与 TM 等价：论题课已声明；本课不写互译。用处是后课组合子、以及逻辑课里的证明即项（那里要类型）。</p><h3 id="β-不是「代入语法糖」" tabindex="-1">β 不是「代入语法糖」 <a class="header-anchor" href="#β-不是「代入语法糖」" aria-label="Permalink to &quot;β 不是「代入语法糖」&quot;">​</a></h3><p>捕获会把自由 \\(x\\) 绑错，必须 α 换名。合流（Church–Rosser）：若有范式则唯一，计算路径可以不同。策略（正则序 / 应用序）影响会不会停，不改变范式（若存在）。</p><p><span class="marginnote">Church 1936/1941。Barendregt 是标准参考。无类型 λ 图灵完全；简单类型 λ 反而弱，不够当全部可计算，后课证明助手再加依值类型。</span></p><p><span class="marginnote">数字实例：Church 数字 \\(\\overline{3}=\\lambda f.\\lambda x.\\,f(f(f\\,x))\\)——「3」就是「把 \\(f\\) 连套三遍」。取 \\(f\\) 为后继、\\(x\\) 为 0，\\(\\overline{3}\\,\\mathrm{succ}\\,0\\) 归约出 \\(3\\)；加法就是多套一层，整数在这里不是原语而是迭代次数。</span></p><p><span class="marginnote">术语翻译：α 换名就是「给绑定的局部变量改个名」——把「对每个学生 \\(x\\)……」改说成「对每个学生 \\(s\\)……」，意思不变。它是躲开变量捕获事故的唯一正规手段：先把撞名的绑定改名，再做 β 代入。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写几个项：恒等 \\(I=\\lambda x.x\\)，真假 \\(\\mathrm{T}=\\lambda xy.x\\)，\\(\\mathrm{F}=\\lambda xy.y\\)，数字 \\(\\overline n=\\lambda fx.f^n x\\)。加法、后继是项。强调：数据与函数同一语法。不要把 Python 的 <code>lambda</code> 当定义——那是有环境的闭包，归约策略由语言定。</p>',13)),(o(),E(d,null,{default:l(()=>[s(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20VAR%5B%22%E5%8F%98%E9%87%8F%22%5D%20--%3E%20ABS%5B%22%CE%BBx.M%22%5D%0A%20%20ABS%20--%3E%20APP%5B%22%E5%BA%94%E7%94%A8%20MN%22%5D%0A%20%20APP%20--%3E%20BETA%5B%22%CE%B2%20%E5%BD%92%E7%BA%A6%22%5D%0A%20%20BETA%20--%3E%20NF%5B%22%E8%8C%83%E5%BC%8F%E6%88%96%E5%BE%AA%E7%8E%AF%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("a",{href:"/cs/recursion-theorem"},"递归定理"),r(" 在 λ 里变成找 \\(F\\) 的不动点项，下一课 \\(Y\\)。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"计算 = 改写，没有带与头。不可判定性平移：是否有范式不可判定，等于停机。本课不重做对角化。名字绑定是后课类型论的预演，本课只要求会画自由/约束。",-1)),a[6]||(a[6]=e("p",null,"不要在无类型 λ 里谈「类型错误」：每个项都可以应用。",-1)),a[7]||(a[7]=e("p",null,"Church 数字把迭代交给项：\\(\\overline{m}\\,\\overline{n}\\) 不是整数乘，要另写乘项。布尔、序对、列表都可以编码，故「数据」不是原语。无范式的项对应循环；正规序（先最左外约）对有范式的项保证找到范式，应用序可能先循环。实现语言选策略，理论先承认合流。",-1)),(o(),E(d,null,{default:l(()=>[s(t,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%E9%A1%B9%3A%20(%CE%BBx.%CE%BBy.y)%20%CE%A9%22%5D%20--%3E%20NORM%5B%22%E6%AD%A3%E8%A7%84%E5%BA%8F%3A%20%E5%85%88%E7%BA%A6%E6%9C%80%E5%A4%96%E5%B1%82%22%5D%0A%20%20NORM%20--%3E%20N2%5B%22%E6%8A%8A%20%CE%A9%20%E5%8E%9F%E5%B0%81%E4%B8%8D%E5%8A%A8%E5%BD%93%20x%2C%20%E4%B8%BB%E4%BD%93%E6%A0%B9%E6%9C%AC%E4%B8%8D%E7%94%A8%E5%AE%83%22%5D%0A%20%20N2%20--%3E%20N3%5B%22%E5%BE%97%20%CE%BBy.y%2C%20%E5%81%9C%22%5D%0A%20%20T%20--%3E%20APP%5B%22%E5%BA%94%E7%94%A8%E5%BA%8F%3A%20%E5%85%88%E7%BA%A6%E5%8F%82%E6%95%B0%22%5D%0A%20%20APP%20--%3E%20A2%5B%22%E5%8E%BB%E7%BA%A6%20%CE%A9%20%3D%20(%CE%BBx.xx)(%CE%BBx.xx)%22%5D%0A%20%20A2%20--%3E%20A3%5B%22%E4%B8%80%E6%AD%A5%E4%B9%8B%E5%90%8E%E8%BF%98%E6%98%AF%20%CE%A9%2C%20%E6%B0%B8%E4%B8%8D%E5%81%9C%E6%AD%A2%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=n('<p><span class="marginnote">常见误区：初学者容易把 Python 的 <code>lambda</code> 当成 λ 演算本体。Python 的 lambda 是带环境的闭包，求值时机由解释器说了算；λ 演算里没有「环境」这个原语，α 换名与 β 归约本身就是全部机制。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入简单类型、Hindley–Milner、惰性求值实现。不写 Y 组合子的展开。后课默认：λ 项 + β 是可计算模型；数字用 Church 编码。下一课去掉名字：组合子与不动点。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>λ 项：抽象与应用；计算是 β。</li><li>有范式对应停机；与 TM 等价已由论题对齐。</li><li>数据亦项；换名避免捕获。</li><li>出处：Church, 1941；Barendregt。</li></ul>',5))])}const T=i(m,[["render",h]]);export{f as __pageData,T as default};
